// API @jinx-ui/react здесь принята по соглашению (Table*/Badge/Pagination) — сверьте имена с версией пакета.
import { useMemo, useState } from 'react';
import {
  Badge,
  Pagination,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
} from '@jinx-ui/react';

const PAGE_SIZE = 10;

export interface User {
  id: string;
  name: string;
  role: string;
  active: boolean;
}

export interface UsersTableProps {
  users: User[];
}

export default function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);

  const rows = useMemo(
    () => users.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE),
    [users, currentPage],
  );

  return (
    <Stack direction="column" gap="var(--jx-space-4)">
      <Table>
        <TableHead>
          <TableRow>
            <TableCell as="th">Имя</TableCell>
            <TableCell as="th">Роль</TableCell>
            <TableCell as="th">Статус</TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {rows.map((user) => (
            <TableRow key={user.id}>
              <TableCell>{user.name}</TableCell>
              <TableCell>{user.role}</TableCell>
              <TableCell>
                <Badge color={user.active ? 'success' : 'neutral'}>
                  {user.active ? 'Активен' : 'Отключён'}
                </Badge>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>

      <Pagination page={currentPage} pageCount={pageCount} onPageChange={setPage} />
    </Stack>
  );
}

